mod solution;

fn main() {
    let cases = [
    (r#"[0, 4, 0, 2, 7, 0]"#, r#"4,2,7"#),
    (r#"[0, 0, 5]"#, r#"5"#),
    (r#"
[0, 0, 5]
"#, r#"5"#),
    (r#"  
[0, 4, 0, 2, 7, 0]
  "#, r#"4,2,7"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS stable-compaction");
}
